import java.lang.reflect.*;
import java.util.*;

interface Task { void run(); }
class TaskImpl implements Task { public void run() { System.out.println("    [target] run()"); } }
interface Interceptor { Object proceed(MethodInvocation mi) throws Throwable; }
class MethodInvocation {
    Object target; Method m; List<Interceptor> chain; int idx = 0;
    MethodInvocation(Object t, Method m, List<Interceptor> c) { target = t; this.m = m; chain = c; }
    Object proceed() throws Throwable {
        if (idx == chain.size()) return m.invoke(target);
        Interceptor ic = chain.get(idx++);
        return ic.proceed(this);
    }
}
class Tracing implements Interceptor { public Object proceed(MethodInvocation mi) throws Throwable {
    System.out.println("[1 tracing] before"); Object r = mi.proceed(); System.out.println("[1 tracing] after"); return r; } }
class Security implements Interceptor { public Object proceed(MethodInvocation mi) throws Throwable {
    System.out.println("[2 security] check"); return mi.proceed(); } }
class Tx implements Interceptor { public Object proceed(MethodInvocation mi) throws Throwable {
    System.out.println("[3 tx] begin"); Object r = mi.proceed(); System.out.println("[3 tx] commit"); return r; } }
class ProxyHandler implements InvocationHandler {
    Object target; List<Interceptor> chain;
    ProxyHandler(Object t, List<Interceptor> c) { target = t; chain = c; }
    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
        return new MethodInvocation(target, m, chain).proceed();
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        List<Interceptor> c = new ArrayList<>();
        c.add(new Tracing()); c.add(new Security()); c.add(new Tx());
        Task proxy = (Task) Proxy.newProxyInstance(Task.class.getClassLoader(),
            new Class[]{Task.class}, new ProxyHandler(new TaskImpl(), c));
        proxy.run();
    }
}
